practice_tasks.solution:
from functools import lru_cache

@lru_cache(maxsize=None)
def count_paths(r, c):
    if r == 0 or c == 0:
        return 1
    return count_paths(r-1, c) + count_paths(r, c-1)

print(count_paths(15, 15))

